/// GET /mail/messages/stats/read-rate-by-tier — taxa lidas × tier. Sprint #1952.
async fn read_rate_by_tier_stats(
    State(state): State<AppState>,
    ctx:          RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "SELECT CASE WHEN m.size = 0 THEN 'empty' \
                     WHEN m.size < 1024 THEN 'tiny' \
                     WHEN m.size < 10240 THEN 'small' \
                     WHEN m.size < 102400 THEN 'medium' \
                     WHEN m.size < 1048576 THEN 'large' \
                     ELSE 'huge' END AS tier, \
         COUNT(*) FILTER (WHERE m.seen)::BIGINT AS read_count, \
         COUNT(*)::BIGINT AS message_count \
         FROM messages m JOIN mailboxes mb ON mb.id = m.mailbox_id \
         WHERE m.tenant_id = $1 AND mb.tenant_id = $1 AND mb.user_id = $2 \
         GROUP BY tier ORDER BY message_count DESC",
    )
    .bind(ctx.tenant_id)
    .bind(ctx.user_id)
    .fetch_all(&mut *tx)
    .await?;
    tx.commit().await?;
    let result: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|(tier, read_cnt, total)| {
            let rate = if total > 0 { read_cnt as f64 / total as f64 } else { 0.0 };
            serde_json::json!({"tier": tier, "read_count": read_cnt, "message_count": total, "read_rate": rate})
        })
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

