/// GET /mail/messages/stats/size-gini-by-folder — coeficiente de Gini de size por pasta. Sprint #2727.
async fn size_gini_by_folder_stats(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = state.begin_tenant_tx(ctx.tenant_id).await.map_err(|e| {
        (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()})))
    })?;
    let rows: Vec<(String, Vec<f64>, i64)> = sqlx::query_as(
        "SELECT mb.name AS folder, \
                ARRAY_AGG(m.size::FLOAT8 ORDER BY m.size) AS sizes, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         WHERE m.tenant_id = $1 AND m.user_id = $2 AND m.size IS NOT NULL \
         GROUP BY mb.name, m.mailbox_id ORDER BY mb.name",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result: Vec<serde_json::Value> = rows.into_iter().map(|(folder, sizes, cnt)| {
        let n = sizes.len() as f64;
        let total: f64 = sizes.iter().sum();
        let gini = if total > 0.0 && n > 1.0 {
            let num: f64 = sizes.iter().enumerate().map(|(i, x)| (2.0 * (i as f64 + 1.0) - n - 1.0) * x).sum();
            num / (n * total)
        } else { 0.0 };
        serde_json::json!({"folder": folder, "gini_size": gini, "message_count": cnt})
    }).collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

